pcall(function()
	if genv._PremiumFlyCleanup then genv._PremiumFlyCleanup() end
end)

------------------------------------------------------------------------ settings
local FOLDER, FILE = "PremiumFly", "PremiumFly/settings.json"
local S = { speed = 60, smooth = 0.18, color = 1, trail = true, aura = true, fov = true, pose = true, noclip = false, boost = false, mode = 1, cruise = false, lines = true, sound = true, trailLen = 0.55 }
local MODES = { { name = "GLIDE", sm = 1.9, sp = 1.0 }, { name = "SPORT", sm = 0.6, sp = 1.5 }, { name = "PRECISE", sm = 0.4, sp = 0.4 } }
pcall(function()
	if isfile and isfile(FILE) then
		local d = HttpService:JSONDecode(readfile(FILE))
		if type(d) == "table" then
			for k, v in pairs(d) do
				if S[k] ~= nil and type(v) == type(S[k]) then S[k] = v end
			end
		end
	end
end)
local saveQueued = false
local function save()
	if saveQueued then return end
	saveQueued = true
	task.delay(0.6, function()
		saveQueued = false
		pcall(function()
			if makefolder and isfolder and not isfolder(FOLDER) then makefolder(FOLDER) end
			writefile(FILE, HttpService:JSONEncode(S))
		end)
	end)
end

------------------------------------------------------------------------ helpers
local function new(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props or {}) do o[k] = v end
	if parent then o.Parent = parent end
	return o
end
local function corner(o, r) return new("UICorner", { CornerRadius = UDim.new(0, r) }, o) end
local function stroke(o, th, col, tr)
	return new("UIStroke", { Thickness = th, Color = col or Color3.new(1, 1, 1), Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o)
end
local function tw(o, t, props, style, dir)
	local tween = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
	tween:Play()
	return tween
end
local function C3(r, g, b) return Color3.fromRGB(r, g, b) end
local WHITE = Color3.new(1, 1, 1)
local COLORS = { C3(0, 225, 255), C3(170, 100, 255), C3(255, 200, 60), C3(255, 60, 90), C3(50, 255, 150), C3(255, 90, 200), C3(235, 242, 255) }
local ACC = COLORS[S.color] or COLORS[1]
local accentFns = {}
local function onAccent(fn) accentFns[#accentFns + 1] = fn fn(ACC) end
local function setAccent(i)
	S.color = i
	ACC = COLORS[i]
	for _, f in ipairs(accentFns) do pcall(f, ACC) end
	save()
end
local function shineOf(c) return c:Lerp(WHITE, 0.55) end
local function darkOf(c) return c:Lerp(Color3.new(0, 0, 0), 0.7) end
local function seq3(a, b, c) return ColorSequence.new({ ColorSequenceKeypoint.new(0, a), ColorSequenceKeypoint.new(0.5, b), ColorSequenceKeypoint.new(1, c) }) end

------------------------------------------------------------------------ sound (embedded, written to PremiumFly/ once)
local SND = {
	take = "",
	land = "",
	click = "",
	on = "",
	off = "",
	tab = "",
	warp = "",
	wind = "",
}

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64map = {}
for i = 1, 64 do b64map[B64:byte(i)] = i - 1 end
local function b64dec(str)
	local out, buf = {}, {}
	local len = #str
	for i = 1, len - 3, 4 do
		local a, b, c, d = str:byte(i, i + 3)
		local pad = (d == 61 and 1 or 0) + (c == 61 and 1 or 0)
		local v = b64map[a] * 262144 + b64map[b] * 4096 + (b64map[c] or 0) * 64 + (b64map[d] or 0)
		local b1, b2, b3 = math.floor(v / 65536), math.floor(v / 256) % 256, v % 256
		if pad == 0 then buf[#buf + 1] = string.char(b1, b2, b3)
		elseif pad == 1 then buf[#buf + 1] = string.char(b1, b2)
		else buf[#buf + 1] = string.char(b1) end
		if #buf >= 2000 then out[#out + 1] = table.concat(buf) buf = {} end
	end
	out[#out + 1] = table.concat(buf)
	return table.concat(out)
end
local assetCache = {}
local function assetFor(name)
	if assetCache[name] ~= nil then return assetCache[name] or nil end
	local ok, id = pcall(function()
		if not (writefile and getcustomasset and SND[name]) then error("unsupported") end
		if makefolder and isfolder and not isfolder(FOLDER) then makefolder(FOLDER) end
		local path = FOLDER .. "/snd_" .. name .. "_v1.ogg"
		if not (isfile and isfile(path)) then writefile(path, b64dec(SND[name])) end
		return getcustomasset(path)
	end)
	assetCache[name] = ok and id or false
	return ok and id or nil
end
local SoundHost
local function play(name, vol, speed)
	if not S.sound then return end
	local id = assetFor(name)
	if not id then return end
	local snd = new("Sound", { SoundId = id, Volume = vol or 0.5, PlaybackSpeed = speed or 1 }, SoundHost or workspace)
	snd:Play()
	Debris:AddItem(snd, 5)
	return snd
end

