local function paintTabs(instant)
	for i, b in ipairs(tabBtns) do
		local on = i == curTab
		tw(b, instant and 0 or 0.25, { BackgroundColor3 = on and darkOf(ACC):Lerp(ACC, 0.4) or C3(18, 18, 26), TextColor3 = on and WHITE or C3(140, 140, 160) })
