local function showTab(i, silent)
	if not silent then play("tab", 0.35) end
	curTab = i
	for k, pg in ipairs(pages) do
		if k == i then
			pg.Visible = true
			pg.Position = UDim2.fromOffset(i == 1 and -14 or 14, 88)
			tw(pg, 0.35, { Position = UDim2.fromOffset(0, 88) })
		else
			pg.Visible = false
		end
	end
	paintTabs(silent)
end
