------------------------------------------------------------------------ sliders
local function slider(parent, y, name, mn, mx, def, fmt, cb)
	new("TextLabel", { BackgroundTransparency = 1, Text = name, Font = Enum.Font.GothamBold, TextSize = 10, TextColor3 = C3(170, 170, 190), TextXAlignment = Enum.TextXAlignment.Left, Position = UDim2.fromOffset(18, y), Size = UDim2.fromOffset(150, 14), ZIndex = 5 }, parent)
	local val = new("TextLabel", { BackgroundTransparency = 1, Text = "", Font = Enum.Font.RobotoMono, TextSize = 11, TextColor3 = ACC, TextXAlignment = Enum.TextXAlignment.Right, Position = UDim2.new(1, -118, 0, y), Size = UDim2.fromOffset(100, 14), ZIndex = 5 }, parent)
	onAccent(function(c) val.TextColor3 = c end)
	local track = new("Frame", { BackgroundColor3 = C3(28, 28, 38), BorderSizePixel = 0, Position = UDim2.fromOffset(18, y + 22), Size = UDim2.new(1, -36, 0, 6), ZIndex = 5 }, parent)
	corner(track, 4)
	local fill = new("Frame", { BackgroundColor3 = WHITE, BorderSizePixel = 0, Size = UDim2.fromScale(0, 1), ZIndex = 6 }, track)
	corner(fill, 4)
	local fg = new("UIGradient", {}, fill)
	local knob = new("Frame", { BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(16, 16), ZIndex = 8 }, track)
	corner(knob, 8)
	local ks = stroke(knob, 2, ACC, 0)
	onAccent(function(c) fg.Color = ColorSequence.new(darkOf(c), c) ks.Color = c end)
	local hit = new("TextButton", { Text = "", BackgroundTransparency = 1, Position = UDim2.fromOffset(-8, -12), Size = UDim2.new(1, 16, 1, 24), ZIndex = 9 }, track)
	local function set(v, silent)
		v = math.clamp(v, mn, mx)
		local a = (v - mn) / (mx - mn)
		fill.Size = UDim2.fromScale(a, 1)
		knob.Position = UDim2.fromScale(a, 0.5)
		val.Text = string.format(fmt, fmt:find("%%d") and math.floor(v + 0.5) or v)
		if not silent then cb(v) end
	end
	local dragging = false
	local function fromX(x)
		local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		set(mn + (mx - mn) * a)
	end
	hit.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			tw(knob, 0.12, { Size = UDim2.fromOffset(21, 21) })
			fromX(i.Position.X)
		end
	end)
	UIS.InputChanged:Connect(function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then fromX(i.Position.X) end
	end)
	UIS.InputEnded:Connect(function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
			dragging = false
			tw(knob, 0.2, { Size = UDim2.fromOffset(16, 16) }, Enum.EasingStyle.Back)
			save()
		end
	end)
	set(def, true)
	return set
end
local speedSet = slider(pF, 168, "FLY SPEED", 5, 300, S.speed, "%d studs/s", function(v) S.speed = math.floor(v + 0.5) end)

-- generic small button / chip painter
local function pill(parent, x, y, w, text, h)
	local b = new("TextButton", { Text = text, Font = Enum.Font.GothamBold, TextSize = 10, TextColor3 = C3(150, 150, 170), AutoButtonColor = false, BackgroundColor3 = C3(18, 18, 26), BorderSizePixel = 0, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h or 26), ZIndex = 5 }, parent)
	corner(b, 13)
	local st = stroke(b, 1.2, C3(50, 50, 68), 0.1)
	local sc = new("UIScale", {}, b)
	b.MouseButton1Down:Connect(function() tw(sc, 0.07, { Scale = 0.94 }) end)
	b.MouseButton1Up:Connect(function() tw(sc, 0.25, { Scale = 1 }, Enum.EasingStyle.Back) end)
	b.MouseLeave:Connect(function() tw(sc, 0.15, { Scale = 1 }) end)
	local function paint(on, instant)
		local t = instant and 0 or 0.2
		tw(b, t, { BackgroundColor3 = on and darkOf(ACC):Lerp(ACC, 0.35) or C3(18, 18, 26), TextColor3 = on and WHITE or C3(150, 150, 170) })
		tw(st, t, { Color = on and ACC or C3(50, 50, 68) })
	end
	return b, paint
end

