-- toggle chips
local chipPaints = {}
local function chip(parent, col, y, text, key, onChange)
	local b, paint = pill(parent, 16 + col * 92, y, 84, text)
	chipPaints[key] = function(instant) paint(S[key], instant) end
	b.MouseButton1Click:Connect(function()
		S[key] = not S[key]
		chipPaints[key](false)
		play(S[key] and "on" or "off", 0.35)
		save()
		if onChange then onChange(S[key]) end
	end)
end
