------------------------------------------------------------------------ fly engine
F = { on = false, stopping = false, vel = Vector3.new(0, 0, 0), up = false, down = false, shift = false, leanP = 0, leanR = 0, poseW = 0, t = 0, punch = 0, fovBase = 70, joints = {}, fx = {}, parts = {} }
local controls
pcall(function()
	controls = require(lp:WaitForChild("PlayerScripts"):WaitForChild("PlayerModule", 3)):GetControls()
end)
local function moveVec(cam, hum)
	if controls then
		local ok, v = pcall(function() return controls:GetMoveVector() end)
		if ok and v then return v end
	end
	return cam.CFrame:VectorToObjectSpace(hum.MoveDirection)
end
local function getChar()
	local ch = lp.Character
	if not ch then return end
	return ch, ch:FindFirstChild("HumanoidRootPart"), ch:FindFirstChildOfClass("Humanoid")
end
local function ring(pos, size, col, thick)
	local p = new("Part", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, Material = Enum.Material.Neon, Color = col, Shape = Enum.PartType.Cylinder, Size = Vector3.new(thick or 0.3, 2, 2), CFrame = CFrame.new(pos) * CFrame.Angles(0, 0, math.pi / 2), Transparency = 0.1 }, workspace)
	tw(p, 0.9, { Size = Vector3.new(0.1, size, size), Transparency = 1 }, Enum.EasingStyle.Quint)
	Debris:AddItem(p, 1.1)
end
local function groundPos(ch, hrp)
	local params = RaycastParams.new()
	params.FilterDescendantsInstances = { ch }
	params.FilterType = Enum.RaycastFilterType.Exclude
	local r = workspace:Raycast(hrp.Position, Vector3.new(0, -14, 0), params)
	if r then return r.Position + Vector3.new(0, 0.25, 0) end
	return hrp.Position - Vector3.new(0, 3, 0)
end

local function grabJoints(ch)
	F.joints = {}
	local list = {
		{ "RightShoulder", "arm", 0 }, { "LeftShoulder", "arm", 0 },
		{ "RightHip", "leg", 0 }, { "LeftHip", "leg", math.pi },
	}
	for _, it in ipairs(list) do
		local m = ch:FindFirstChild(it[1], true)
		if m and m:IsA("Motor6D") then F.joints[#F.joints + 1] = { m = m, orig = m.C0, kind = it[2], ph = it[3] } end
	end
end
local function restoreJoints()
	for _, j in ipairs(F.joints) do pcall(function() j.m.C0 = j.orig end) end
	F.joints = {}
end

local function buildFx(ch, hrp)
	for _, o in ipairs(F.fx) do pcall(function() o:Destroy() end) end
	F.fx = {}
	F.trails, F.aura = {}, nil
	local names = { "RightHand", "LeftHand", "RightFoot", "LeftFoot" }
	if not ch:FindFirstChild("RightHand") then names = { "Right Arm", "Left Arm", "Right Leg", "Left Leg" } end
	for _, n in ipairs(names) do
		local part = ch:FindFirstChild(n)
		if part then
			local a0 = new("Attachment", { Position = Vector3.new(0, 0.35, 0) }, part)
			local a1 = new("Attachment", { Position = Vector3.new(0, -0.35, 0) }, part)
			local t = new("Trail", { Attachment0 = a0, Attachment1 = a1, Lifetime = S.trailLen, LightEmission = 1, MinLength = 0.05, Enabled = false, Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1) }), WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }) }, part)
			F.fx[#F.fx + 1], F.fx[#F.fx + 2], F.fx[#F.fx + 3] = a0, a1, t
			F.trails[#F.trails + 1] = t
		end
	end
	F.aura = new("ParticleEmitter", { Texture = "rbxasset://textures/particles/sparkles_main.dds", Rate = 0, Lifetime = NumberRange.new(0.6, 1.1), Speed = NumberRange.new(1, 4), SpreadAngle = Vector2.new(180, 180), LightEmission = 1, Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.7), NumberSequenceKeypoint.new(1, 0) }), Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1) }), RotSpeed = NumberRange.new(-90, 90), Enabled = false }, hrp)
	F.fx[#F.fx + 1] = F.aura
end
onAccent(function(c)
	local cs = ColorSequence.new(shineOf(c), c)
	for _, t in ipairs(F.trails or {}) do pcall(function() t.Color = cs end) end
	if F.aura then pcall(function() F.aura.Color = cs end) end
end)
local function applyFxState(on)
	for _, t in ipairs(F.trails or {}) do pcall(function() t.Enabled = on and S.trail end) end
	if F.aura then pcall(function() F.aura.Rate = (on and S.aura) and 30 or 0 F.aura.Enabled = on and S.aura end) end
end

local touchUp, touchDown
local function setUi(on, stateText)
	orbMain.TextColor3 = on and C3(8, 8, 12) or WHITE
	orbSub.TextColor3 = on and C3(8, 8, 12) or C3(150, 150, 170)
	orbSub.Text = on and "TAP TO LAND" or "TAP TO START"
	tw(orbFill, 0.4, { BackgroundTransparency = on and 0 or 1 })
	stState.Text = stateText or (on and "FLYING" or "IDLE")
	if touchUp then touchUp.Visible = on touchDown.Visible = on end
end

local function startFly()
	if F.on then return end
	local ch, hrp, hum = getChar()
	if not (ch and hrp and hum) then return end
	if F.stopping then return end
	F.on = true
	F.t = 0
	hum.PlatformStand = true
	hum.AutoRotate = false
	F.bv = new("BodyVelocity", { MaxForce = Vector3.new(1e9, 1e9, 1e9), Velocity = Vector3.new(0, 0, 0) }, hrp)
	F.bg = new("BodyGyro", { MaxTorque = Vector3.new(1e9, 1e9, 1e9), P = 20000, D = 900, CFrame = hrp.CFrame }, hrp)
	grabJoints(ch)
	buildFx(ch, hrp)
	local cs = ColorSequence.new(shineOf(ACC), ACC)
	for _, t in ipairs(F.trails) do t.Color = cs end
	if F.aura then F.aura.Color = cs end
	F.lastCF = hrp.CFrame
	F.leanP, F.leanR = 0, 0
	local cam = workspace.CurrentCamera
	F.fovBase = cam and cam.FieldOfView or 70
	-- TAKEOFF: impulse up, shock rings, dust/spark burst, FOV punch
	F.vel = Vector3.new(0, 46, 0)
	F.punch = 1
	play("take", 0.8)
	F.wind = assetFor("wind") and new("Sound", { SoundId = assetFor("wind"), Looped = true, Volume = 0, PlaybackSpeed = 0.8 }, SoundHost) or nil
	if F.wind and S.sound then F.wind:Play() end
	local gp = groundPos(ch, hrp)
	ring(gp, 34, ACC, 0.35)
	task.delay(0.12, function() ring(gp, 52, shineOf(ACC), 0.2) end)
	if F.aura then F.aura:Emit(40) end
	applyFxState(true)
	setUi(true, "TAKEOFF")
	tw(orbScale, 0.12, { Scale = 1.12 })
	task.delay(0.14, function() tw(orbScale, 0.45, { Scale = 1 }, Enum.EasingStyle.Back) end)
	task.delay(0.9, function() if F.on then stState.Text = "FLYING" end end)
end

local function finishStop()
	F.stopping = false
	if F.wind then pcall(function() F.wind:Stop() F.wind:Destroy() end) F.wind = nil end
	local ch, hrp, hum = getChar()
	if F.bv then F.bv:Destroy() F.bv = nil end
	if F.bg then F.bg:Destroy() F.bg = nil end
	restoreJoints()
	for _, o in ipairs(F.fx) do pcall(function() o:Destroy() end) end
	F.fx, F.trails, F.aura = {}, {}, nil
	if hum then
		hum.PlatformStand = false
		hum.AutoRotate = true
		pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
	end
	if hrp then
		local look = hrp.CFrame.LookVector
		look = Vector3.new(look.X, 0, look.Z)
		if look.Magnitude < 0.05 then look = Vector3.new(0, 0, -1) end
		hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + look.Unit)
		hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
	end
	local cam = workspace.CurrentCamera
	if cam then tw(cam, 0.4, { FieldOfView = F.fovBase }) end
end

local function stopFly()
	if not F.on then return end
	F.on = false
	F.stopping = true
	F.stopT = os.clock()
	applyFxState(false)
	play("land", 0.7)
	setUi(false, "LANDING")
	local ch, hrp = getChar()
	if ch and hrp then ring(groundPos(ch, hrp), 22, ACC, 0.25) end
	task.delay(0.5, function() if not F.on then stState.Text = "IDLE" end end)
end
local function toggleFly()
	if F.on then stopFly() else startFly() end
end
orb.MouseButton1Click:Connect(toggleFly)

local function stepFly(dt)
	F.t = F.t + dt
	local ch, hrp, hum = getChar()
	if not (ch and hrp and hum and F.bv and F.bg) then
		if F.on then F.on = false setUi(false) end
		return
	end
	local cam = workspace.CurrentCamera
	local cf = cam.CFrame
	local md = MODES[S.mode] or MODES[1]
	local sp = S.speed * md.sp * ((F.shift or S.boost) and 2 or 1)
	local target = Vector3.new(0, 0, 0)
	if F.on then
		local mv = moveVec(cam, hum)
		local vert = (F.up and 1 or 0) - (F.down and 1 or 0)
		local dir = cf.LookVector * (-mv.Z) + cf.RightVector * mv.X + Vector3.new(0, vert, 0)
		if S.cruise then dir = dir + cf.LookVector end
		if dir.Magnitude > 1 then dir = dir.Unit end
		target = dir * sp
	end
	local rate = F.on and math.max(S.smooth * md.sm, 0.01) or 0.12
	F.vel = F.vel:Lerp(target, 1 - math.exp(-dt / rate))
	F.bv.Velocity = F.vel
	-- orientation: face the camera direction, lean forward when moving, bank when strafing
	local look = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
	if look.Magnitude < 0.01 then look = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z) end
	look = look.Unit
	local denom = math.max(sp, 1)
	local fwd = math.clamp(F.vel:Dot(look) / denom, -1, 1)
	local side = math.clamp(F.vel:Dot(cf.RightVector) / denom, -1, 1)
	local lift = math.clamp(F.vel.Y / denom, -1, 1)
	local poseOn = F.on and S.pose
	local tp = poseOn and (-math.rad(72) * math.clamp(fwd, 0, 1) + math.rad(18) * math.clamp(-fwd, 0, 1) - math.rad(10) * math.clamp(lift, 0, 1)) or 0
	local tr = poseOn and (-math.rad(32) * side) or 0
	local k = math.min(1, dt * 7)
	F.leanP = F.leanP + (tp - F.leanP) * k
	F.leanR = F.leanR + (tr - F.leanR) * k
	F.bg.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + look) * CFrame.Angles(F.leanP, 0, F.leanR)
	-- arms / legs pose
	local pw = poseOn and 1 or 0
	F.poseW = F.poseW + (pw - F.poseW) * math.min(1, dt * 6)
	local w = F.poseW
	local armF = 0.25 + 0.75 * math.clamp(fwd, 0, 1)
	local flutter = 0.4 + 0.6 * math.clamp(math.abs(fwd) + math.abs(side), 0, 1)
	for _, j in ipairs(F.joints) do
		if j.kind == "arm" then
			j.m.C0 = j.orig * CFrame.Angles(math.rad(165) * w * armF + math.sin(F.t * 5) * 0.05 * w, 0, 0)
		else
			j.m.C0 = j.orig * CFrame.Angles(-0.38 * w + math.sin(F.t * 9 + j.ph) * 0.12 * w * flutter, 0, 0)
		end
	end
	-- camera FOV rush
	if cam and S.fov then
		F.punch = math.max(0, F.punch - dt * 1.6)
		local want = F.fovBase + (F.on and (F.vel.Magnitude / math.max(S.speed * 2, 1)) * 18 or 0) + F.punch * 14
		cam.FieldOfView = cam.FieldOfView + (want - cam.FieldOfView) * math.min(1, dt * 7)
	end
	-- optional noclip
	if S.noclip and F.on then
		for _, p in ipairs(ch:GetDescendants()) do
			if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
		end
	end
	-- trail / aura intensity follows speed
	if F.aura and F.on then F.aura.Rate = S.aura and (10 + 50 * math.clamp(F.vel.Magnitude / math.max(S.speed, 1), 0, 2)) or 0 end
	-- wind sound follows speed
	if F.wind then
		local n = math.clamp(F.vel.Magnitude / 220, 0, 1)
		F.wind.Volume = S.sound and (0.04 + n * 0.5) or 0
		F.wind.PlaybackSpeed = 0.7 + n * 0.8
	end
	-- finish landing
	if F.stopping and os.clock() - (F.stopT or 0) > 0.4 and F.vel.Magnitude < 6 or (F.stopping and os.clock() - (F.stopT or 0) > 0.9) then
		finishStop()
	end
end


------------------------------------------------------------------------ mobile buttons
if UIS.TouchEnabled then
	local function tbtn(name, txt, y)
		local b = new("TextButton", { Name = name, Text = txt, Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = WHITE, AutoButtonColor = false, AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -24, 1, y), Size = UDim2.fromOffset(66, 66), BackgroundColor3 = C3(10, 10, 16), BackgroundTransparency = 0.1, Visible = false, BorderSizePixel = 0 }, touchGui)
		corner(b, 33)
		local st = stroke(b, 2, ACC, 0)
		onAccent(function(c) st.Color = c end)
		return b
	end
	touchUp, touchDown = tbtn("Up", "UP", -120), tbtn("Down", "DOWN", -44)
	local function hold(b, key)
		b.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
				F[key] = true
				tw(b, 0.1, { BackgroundTransparency = 0.5 })
			end
		end)
		b.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
				F[key] = false
				tw(b, 0.2, { BackgroundTransparency = 0.1 })
			end
		end)
	end
	hold(touchUp, "up")
	hold(touchDown, "down")
end

------------------------------------------------------------------------ input
local conns = {}
local function track(c) conns[#conns + 1] = c return c end
track(UIS.InputBegan:Connect(function(i, gp)
	if gp then return end
	local k = i.KeyCode
	if k == Enum.KeyCode.F then toggleFly()
	elseif k == Enum.KeyCode.C then
		S.cruise = not S.cruise
		chipPaints.cruise(false)
		play(S.cruise and "on" or "off", 0.35)
		save()
	elseif k == Enum.KeyCode.Space or k == Enum.KeyCode.E then F.up = true
	elseif k == Enum.KeyCode.Q or k == Enum.KeyCode.LeftControl then F.down = true
	elseif k == Enum.KeyCode.LeftShift then F.shift = true
	elseif k == Enum.KeyCode.RightShift then root.Visible = not root.Visible end
end))
track(UIS.InputEnded:Connect(function(i)
	local k = i.KeyCode
	if k == Enum.KeyCode.Space or k == Enum.KeyCode.E then F.up = false
	elseif k == Enum.KeyCode.Q or k == Enum.KeyCode.LeftControl then F.down = false
	elseif k == Enum.KeyCode.LeftShift then F.shift = false end
end))
track(RunService.RenderStepped:Connect(function(dt)
	if F.on or F.stopping then pcall(stepFly, dt) end
end))
track(lp.CharacterAdded:Connect(function()
	if F.on or F.stopping then
		F.on, F.stopping = false, false
		F.bv, F.bg = nil, nil
		F.joints, F.fx, F.trails, F.aura = {}, {}, {}, nil
		setUi(false)
	end
end))

------------------------------------------------------------------------ window behaviour: drag, minimize, close, idle animation
local dragging, dragStart, startPos = false, nil, nil
header.InputBegan:Connect(function(i)
	if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
		dragging, dragStart, startPos = true, i.Position, root.Position
	end
end)
track(UIS.InputChanged:Connect(function(i)
	if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
		local d = i.Position - dragStart
		root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
	end
end))
track(UIS.InputEnded:Connect(function(i)
	if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
end))

local mini = new("TextButton", { Text = "FLY", Font = Enum.Font.Michroma, TextSize = 11, TextColor3 = WHITE, AutoButtonColor = false, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 46, 0.5, 0), Size = UDim2.fromOffset(56, 56), BackgroundColor3 = C3(10, 10, 16), BorderSizePixel = 0, Visible = false }, gui)
corner(mini, 28)
local miniStroke = stroke(mini, 2.2, WHITE, 0)
local miniGrad = new("UIGradient", {}, miniStroke)
onAccent(function(c) miniGrad.Color = seq3(c, WHITE, darkOf(c)) end)
local miniScale = new("UIScale", { Scale = 0 }, mini)
local minimized = false
local function setMin(v)
	minimized = v
	if v then
		tw(root, 0.25, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
		task.delay(0.25, function() if minimized then root.Visible = false end end)
		mini.Visible = true
		miniScale.Scale = 0
		tw(miniScale, 0.4, { Scale = 1 }, Enum.EasingStyle.Back)
	else
		root.Visible = true
		tw(miniScale, 0.2, { Scale = 0 })
		task.delay(0.2, function() if not minimized then mini.Visible = false end end)
		tw(root, 0.35, { GroupTransparency = 0 })
	end
end
miniB.MouseButton1Click:Connect(function() setMin(true) end)
mini.MouseButton1Click:Connect(function() setMin(false) end)

local function cleanup()
	pcall(function() if F.on then F.on = false end finishStop() end)
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	pcall(function() gui:Destroy() end)
	pcall(function() touchGui:Destroy() end)
	pcall(function() fxGui:Destroy() end)
	genv._PremiumFlyCleanup = nil
end
genv._PremiumFlyCleanup = cleanup
closeB.MouseButton1Click:Connect(function()
	tw(root, 0.25, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)
	task.delay(0.28, cleanup)
end)

-- idle animation: rotating border gradients, pulsing glow ring, title shine
local clock = 0
local vpC = Vector2.new(800, 600)
track(RunService.Heartbeat:Connect(function(dt)
	clock = clock + dt
	rootGrad.Rotation = (clock * 40) % 360
	orbGrad.Rotation = (clock * (F.on and 220 or 70)) % 360
	miniGrad.Rotation = (clock * 90) % 360
	local pulse = math.sin(clock * (F.on and 5 or 2)) * 0.5 + 0.5
	local sz = 108 + pulse * (F.on and 20 or 8)
	glow.Size = UDim2.fromOffset(sz, sz)
	glowStroke.Transparency = F.on and (0.25 + pulse * 0.55) or (0.55 + pulse * 0.35)
	titleGrad.Offset = Vector2.new(((clock * 0.5) % 2.4) - 1.2, 0)
	local flying = F.on or F.stopping
	local spd = flying and F.vel.Magnitude or 0
	if flying then
		stSpeed.Text = tostring(math.floor(spd + 0.5))
		local _, hrp = getChar()
		if hrp then
			stAlt.Text = tostring(math.floor(hrp.Position.Y + 0.5))
			hudTxt.Text = string.format("SPD %d   ALT %d   %s%s", math.floor(spd + 0.5), math.floor(hrp.Position.Y + 0.5), (MODES[S.mode] or MODES[1]).name, S.cruise and "  CRZ" or "")
		end
	end
	local want = F.on and 0 or 1
	hud.GroupTransparency = hud.GroupTransparency + (want - hud.GroupTransparency) * math.min(1, dt * 8)
	hudGrad.Rotation = (clock * 120) % 360
	hudBar.Size = UDim2.new(math.clamp(spd / math.max(S.speed * 2 * (MODES[S.mode] or MODES[1]).sp, 1), 0, 1), 0, 0, 3)
	-- speed lines
	local inten = (F.on and S.lines) and math.clamp((spd / 230 - 0.16) * 1.7, 0, 1) or 0
	vpC = fxGui.AbsoluteSize
	local cx, cy, R = vpC.X / 2, vpC.Y / 2, math.max(vpC.X, vpC.Y) * 0.55
	for _, l in ipairs(LINES) do
		if inten <= 0.01 then
			if l.f.BackgroundTransparency < 1 then l.f.BackgroundTransparency = 1 end
		else
			local r = (clock * (0.55 + inten * 1.8) + l.ph) % 1
			local rad = R * (0.3 + 0.7 * r)
			l.f.Position = UDim2.fromOffset(cx + math.cos(l.a) * rad, cy + math.sin(l.a) * rad)
			l.f.Size = UDim2.fromOffset(2, 24 + 170 * inten * r)
			l.f.Rotation = math.deg(l.a) + 90
			l.f.BackgroundTransparency = 1 - inten * 0.6 * math.sin(math.pi * r)
		end
	end
end))

showTab(1, true)
for _, p in pairs(chipPaints) do p(true) end
paintPresets(true)
paintModes(true)
play("on", 0.4)
-- open animation
root.Position = UDim2.new(0, 16, 0.5, 40)
local rs = root:FindFirstChildOfClass("UIScale")
local target = rs.Scale
rs.Scale = target * 0.88
tw(root, 0.6, { Position = UDim2.new(0, 16, 0.5, 0), GroupTransparency = 0 })
tw(rs, 0.6, { Scale = target }, Enum.EasingStyle.Back)
for i, o in ipairs({ stSpeed.Parent, stAlt.Parent, stState.Parent }) do
	o.BackgroundTransparency = 1
	task.delay(0.25 + i * 0.1, function() tw(o, 0.4, { BackgroundTransparency = 0 }) end)
end
pcall(function()
	game:GetService("StarterGui"):SetCore("SendNotification", { Title = "PREMIUM FLY", Text = "Press F or tap the orb to fly", Duration = 4 })
end)
